def pipeline(raw):
    agg = {}
    errors = 0
    for r in raw:
        try:
            amt = float(r["amount"])
        except (TypeError, ValueError):
            errors += 1
            continue
        if amt < 0:
            errors += 1
            continue
        city = (r.get("city") or "").strip()
        if not city:
            errors += 1
            continue
        a = agg.setdefault(city, {"amount": 0.0, "orders": set()})
        a["amount"] += amt
        a["orders"].add(r["id"])
    report = [
        {"city": c, "amount": round(v["amount"], 2), "orders": len(v["orders"]),
         "aov": round(v["amount"] / len(v["orders"]), 2)}
        for c, v in agg.items()
    ]
    report.sort(key=lambda x: -x["amount"])
    return {"report": report, "errors": errors, "total": len(raw)}
```

